import asyncio
from playwright.async_api import async_playwright

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"

async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch()
        pg = await b.new_page(viewport={"width":1440,"height":900})
        await pg.goto(URL, wait_until="load", timeout=20000)
        await pg.wait_for_timeout(600)
        info = await pg.evaluate("""() => {
          const tes = document.getElementById('tes');
          const hold = document.querySelector('.chapter-hold');
          const tr = tes.getBoundingClientRect();
          const hr = hold.getBoundingClientRect();
          return {
            tesTop: tr.top + window.scrollY,
            tesH: tes.offsetHeight,
            holdTop: hr.top + window.scrollY,
            holdH: hold.offsetHeight,
          };
        }""")
        print(info)
        pinEnd = info['tesTop'] + info['tesH'] - 900
        print("pinEnd (ridaY(0)):", pinEnd)
        # scan for when the first process step band becomes visible (data-step 01 li top reaching viewport)
        for offset in range(0, 260, 10):
            y = pinEnd + offset*900/100
            await pg.evaluate(f"window.scrollTo(0,{y})")
            await pg.wait_for_timeout(40)
            r = await pg.evaluate("""() => {
              const li01 = document.querySelector('.process-steps li[data-step=\"01\"]');
              const chap = document.querySelector('.process-chapter');
              const lr = li01.getBoundingClientRect();
              const cr = chap.getBoundingClientRect();
              return {li01Top: lr.top, li01Visible: lr.top < 900 && lr.bottom > 0, chapTop: cr.top, chapVisible: cr.top < 900 && cr.bottom > 0};
            }""")
            print(f"intoVh={offset}", r)
        await b.close()
asyncio.run(main())
EOF

