import asyncio
from playwright.async_api import async_playwright

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"

async def scan_overlap(pg, container_sel, item_sel, width, height, label):
    await pg.set_viewport_size({"width": width, "height": height})
    await pg.goto(URL, wait_until="load", timeout=20000)
    await pg.wait_for_timeout(500)
    el_top, el_h = await pg.evaluate(f"""() => {{
      const el = document.querySelector('{container_sel}');
      return [el.getBoundingClientRect().top + window.scrollY, el.offsetHeight];
    }}""")
    max_overlap = 0
    frames_with_2 = 0
    total = 0
    for step in range(0, el_h, 20):
        y = el_top + step
        await pg.evaluate(f"window.scrollTo(0,{y})")
        await pg.wait_for_timeout(15)
        rects = await pg.evaluate(f"""() => {{
          const items = [...document.querySelectorAll('{item_sel}')];
          return items.map(it => {{
            const r = it.getBoundingClientRect();
            const cs = getComputedStyle(it);
            // visible height per clip-path inset: crude proxy via actual rect intersect viewport,
            // but real visibility needs clip-path applied bbox - use offsetHeight * (1-out) style calc not available,
            // so measure via elementsFromPoint sampling instead.
            return {{top: r.top, bottom: r.bottom}};
          }});
        }}""")
        # sample glyph visibility via elementFromPoint at several y within each item's box, x at container center
        total += 1
        visible_count = 0
        for idx, r in enumerate(rects):
            # sample 3 points inside this item's own row band
            mid_y = (r['top'] + r['bottom']) / 2
            if 0 <= mid_y <= height:
                hit = await pg.evaluate(f"""(mx,my) => {{
                  const el = document.elementFromPoint(mx,my);
                  return el ? (el.closest('{item_sel}') ? true : false) : false;
                }}""", width*0.25, mid_y)
                if hit:
                    visible_count += 1
        if visible_count > 1:
            frames_with_2 += 1
    print(label, "frames scanned:", total, "frames with >1 visible (elementFromPoint):", frames_with_2)

async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch()
        pg = await b.new_page()
        for w,h,lbl in [(1440,900,"tes-1440"),(768,1024,"tes-768"),(390,844,"tes-390")]:
            await scan_overlap(pg, '#tes', '.ts', w, h, lbl)
        await b.close()
asyncio.run(main())
EOF

