import asyncio, re
from playwright.async_api import async_playwright

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"

def parse_inset(clip):
    # e.g. "inset(12.5% 0% 0% 0%)"
    m = re.findall(r'[-\d.]+%', clip)
    if len(m) != 4: return None
    top, right, bottom, left = [float(x.replace('%','')) for x in m]
    return top, bottom

async def scan(pg, container_sel, item_sel, width, height, label):
    await pg.set_viewport_size({"width": width, "height": height})
    await pg.goto(URL, wait_until="load", timeout=20000)
    await pg.wait_for_timeout(500)
    el_top, el_h = await pg.evaluate(f"""() => {{
      const el = document.querySelector('{container_sel}');
      return [el.getBoundingClientRect().top + window.scrollY, el.offsetHeight];
    }}""")
    max_overlap_px = 0
    worst_y = None
    frames = 0
    for step in range(0, el_h, 20):
        y = el_top + step
        await pg.evaluate(f"window.scrollTo(0,{y})")
        await pg.wait_for_timeout(12)
        data = await pg.evaluate(f"""() => {{
          const items = [...document.querySelectorAll('{item_sel}')];
          return items.map(it => {{
            const r = it.getBoundingClientRect();
            const cs = getComputedStyle(it);
            return {{h: r.height, top: r.top, clip: cs.clipPath}};
          }});
        }}""")
        frames += 1
        ranges = []
        for d in data:
            parsed = parse_inset(d['clip'])
            if not parsed: continue
            topPct, botPct = parsed
            if topPct >= 100 or botPct >= 100: continue  # fully clipped, invisible
            visTop = d['top'] + d['h']*topPct/100
            visBot = d['top'] + d['h']*(1-botPct/100)
            if visBot > visTop:
                ranges.append((visTop, visBot))
        ranges.sort()
        for k in range(len(ranges)-1):
            overlap = ranges[k][1] - ranges[k+1][0]
            if overlap > max_overlap_px:
                max_overlap_px = overlap
                worst_y = y
    print(label, "frames:", frames, "max vertical overlap px:", round(max_overlap_px,1), "at scrollY", worst_y)

async def main():
    async with async_playwright() as p:
        b = await p.chromium.launch()
        pg = await b.new_page()
        for w,h,lbl in [(1440,900,"tes-1440"),(768,1024,"tes-768"),(390,844,"tes-390")]:
