        await pg.add_style_tag(content="""
          .js .ts{--a:calc(var(--i) / 5) !important;--b:calc((var(--i) + 1) / 5) !important;--f:.04 !important;
            --in:clamp(0,calc((var(--sc-ps,0) - var(--a) + var(--f) / 2) / var(--f)),1) !important;
            --out:clamp(0,calc((var(--sc-ps,0) - var(--b) + var(--f) / 2) / var(--f)),1) !important;
          }
        """)
        el_top, el_h = await pg.evaluate("""() => {
          const el = document.querySelector('#tes');
          return [el.getBoundingClientRect().top + window.scrollY, el.offsetHeight];
        }""")
        max_overlap_px = 0
        worst_y = None
        for step in range(0, el_h, 15):
            y = el_top + step
            await pg.evaluate(f"window.scrollTo(0,{y})")
            await pg.wait_for_timeout(10)
            data = await pg.evaluate("""() => {
              const items = [...document.querySelectorAll('.ts')];
              return items.map(it => {
                const r = it.getBoundingClientRect();
                return {h: r.height, top: r.top, clip: getComputedStyle(it).clipPath};
              });
            }""")
            ranges = []
            for d in data:
                parsed = parse_inset(d['clip'])
                if not parsed: continue
                topPct, botPct = parsed
                if topPct >= 100 or botPct >= 100: continue
                visTop = d['top'] + d['h']*topPct/100
                visBot = d['top'] + d['h']*(1-botPct/100)
                if visBot > visTop + 0.5:
                    ranges.append((visTop, visBot))
            ranges.sort()
            for k in range(len(ranges)-1):
                overlap = ranges[k][1] - ranges[k+1][0]
                if overlap > max_overlap_px:
                    max_overlap_px = overlap
                    worst_y = y
        print("OLD FORMULA: max overlap", round(max_overlap_px,1), "at scrollY", worst_y)
        await b.close()
asyncio.run(main())
