/* Astra r7 material_fixes #4, uppföljning: den fasta kvoten +0,15
   (räknad mot h-[130vh]) stämde bara vid 1440 (ramens ih~807px ger
   1,3*ih=1049 > min-h-[1000px], så 130vh-formeln vinner där). Vid 390
   är ramens ih~450px, 1,3*ih=585 < 1000 - Tailwinds min-height-golv
   vinner i stället, den RIKTIGA sektionshöjden är 1000px, inte
   1,3*ih, och kvoten 0,15 landade fel (uppmätt: opacitet 0,81,
   blur 2,5px i stället för 1/0px). 'center' läser elementets EGEN
   offsetHeight vid varje mätning i stället för att anta ett
   förhållande - fungerar rätt oavsett vilken av Tailwinds två klasser
   som råkar vinna vid en given ramhöjd. */
function measureCase(C){
  var f = C.el.querySelector('iframe'), w = f && f.contentWindow, d = f && f.contentDocument;
  if (!d || !d.documentElement) return;
  var ih = w.innerHeight, max = d.documentElement.scrollHeight - ih;
  C.f = f; C.w = w; C.y = C.anchors.map(function(a){
    var el = a[0] === 'top' ? null : d.querySelector(a[0]);
    var t = el ? el.offsetTop : 0;
    var off = a[1] === 'center' ? (el ? (el.offsetHeight - ih) / 2 : 0) : a[1] * ih;
    return Math.max(0, Math.min(max, Math.round(t + off)));
  });
}

