from playwright.sync_api import sync_playwright
from PIL import Image
import numpy as np
import sys, json, os

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"
OUT = "C:/Users/Anton L/anti-slop-design/tests/alunix-r8/runs/V3d/shots/r22"
os.makedirs(OUT, exist_ok=True)

mode = sys.argv[1] if len(sys.argv) > 1 else "real"
inject = None
if mode == "broken":
    # revert to old box-shadow behavior to confirm the check catches it
    inject = ".tes-plane::after{display:none !important;} .tes-plane{box-shadow:inset 0 0 0 2px #fff !important;}"

def measure(pg, w, h, tag):
    r = pg.evaluate("""() => {
      const plane = document.querySelector('.tes-plane');
      const cs = getComputedStyle(plane);
      const rect = plane.getBoundingClientRect();
      const m = /^inset\\(([^)]+)\\)/.exec(cs.clipPath);
      let top=rect.top, right=rect.right, bottom=rect.bottom, left=rect.left;
      if (m) {
        const raw = m[1].trim().split(/\\s+/);
        function val(t,b){return t.endsWith('%')?parseFloat(t)/100*b:parseFloat(t);}
        let it,ir,ib,il;
        if (raw.length===1){it=ir=ib=il=val(raw[0],rect.height);}
        else if (raw.length===2){it=ib=val(raw[0],rect.height);ir=il=val(raw[1],rect.width);}
        else if (raw.length===3){it=val(raw[0],rect.height);ir=il=val(raw[1],rect.width);ib=val(raw[2],rect.height);}
        else {it=val(raw[0],rect.height);ir=val(raw[1],rect.width);ib=val(raw[2],rect.height);il=val(raw[3],rect.width);}
        top=rect.top+it; bottom=rect.bottom-ib; left=rect.left+il; right=rect.right-ir;
      }
      const chapter = document.querySelector('.process-chapter');
      const ccs = getComputedStyle(chapter);
      return {clipTop: top, clipBottom: bottom, clipLeft: left, clipRight: right,
              x1: parseFloat(ccs.getPropertyValue('--x1')) + chapter.getBoundingClientRect().left,
              x4: parseFloat(ccs.getPropertyValue('--x4')) + chapter.getBoundingClientRect().left};
    }""")
    png_path = "%s/contour-%s-%d-%s.png" % (OUT, tag, w, mode)
    pg.screenshot(path=png_path)
    img = np.array(Image.open(png_path).convert("RGB"))
    def col_brightness(x):
        x = int(round(x))
        x = max(0, min(img.shape[1]-1, x))
        col = img[max(0,int(r['clipTop'])+10):int(r['clipBottom'])-10, x]
        return col.mean()
    # scan a window around expected left/right edges for a bright (white-ish) column
    def find_edge_col(expected_x, window=8):
        best_x, best_b = None, -1
        for dx in range(-window, window+1):
            b = col_brightness(expected_x+dx)
            if b > best_b:
                best_b = b; best_x = expected_x+dx
        return best_x, best_b
    left_x, left_b = find_edge_col(r['clipLeft'])
    right_x, right_b = find_edge_col(r['clipRight'])
    base_b = col_brightness((r['clipLeft']+r['clipRight'])/2)
    return {
        "tag": tag, "w": w,
        "clipLeft": round(r['clipLeft'],1), "clipRight": round(r['clipRight'],1),
