40	  const vw=innerWidth, vh=innerHeight;
41	  const plane=document.querySelector('.tes-plane');
42	  const out={y:scrollY, hits:[], plane:null, twoSheets:false, sheet:null};
43	  if(!plane) return out;
44	  const pcs=getComputedStyle(plane);
45	  const pr=plane.getBoundingClientRect();
46	  const ins=parseInset(pcs.clipPath, pr.width, pr.height)||{top:0,right:0,bottom:0,left:0};
47	  const V={left:pr.left+ins.left, right:pr.right-ins.right, top:pr.top+ins.top, bottom:pr.bottom-ins.bottom};
48	  // --tx och --p-edge ar OREGISTRERADE custom properties: getPropertyValue ger
49	  // token-strommen ("clamp(0,calc(...),1)"), inte det berakndade talet. Rakna
50	  // dem ur --sc-ps, som motorn skriver som ett rent tal.
51	  const chap=document.querySelector('.process-chapter');
52	  const cl=(v)=>Math.max(0,Math.min(1,v));
53	  const ps=chap?parseFloat(getComputedStyle(chap).getPropertyValue('--sc-ps')):NaN;
54	  const tx=isNaN(ps)?NaN:cl((ps-0.07)/0.29);
55	  const edgeOn=isNaN(tx)?0:cl((tx-0.6)/0.3);
56	  out.plane={pos:pcs.position, tx:tx, edge:edgeOn,
57	             vis:[Math.round(V.left),Math.round(V.top),Math.round(V.right),Math.round(V.bottom)],
58	             onScreen:(V.bottom>0 && V.top<vh && V.right>0 && V.left<vw && V.right>V.left && V.bottom>V.top)};
59	  const sh=document.querySelector('.process-sheet');
60	  if(sh){
61	    const sr=sh.getBoundingClientRect();
62	    out.sheet=[Math.round(sr.left),Math.round(sr.top),Math.round(sr.right),Math.round(sr.bottom)];
63	    out.twoSheets = out.plane.onScreen && edgeOn>0.05 && sr.bottom>0 && sr.top<vh && sr.height>40;
64	  }
65	  // .tes-plane och .seam har pointer-events:none och syns DARFOR aldrig i
66	  // elementsFromPoint (forsta forsoket gav 0 aven pa en trasig kontroll -
67	  // matte ingenting). Geometriskt prov i stallet: planets synliga rektangel
68	  // och varje .seam-linjes synliga rektangel mot varje LEVANDE textelements
69	  // rektangel. Traff = overlapp som inte doljs av ett opakt forfaderelement
70	  // (.step-band har egen background; .process-title/.process-locked har inte -
71	  // exakt den skillnad R20 pekade ut).
72	  function ancestorOpaqueCover(el, rect){
73	    let n=el, d=0;
74	    while(n && n.nodeType===1 && d<8){
75	      d++;
76	      // en forfader som SJALV innehaller planet malar UNDER planet och kan
77	      // darfor aldrig dolja det (R20: .step-band doljer, #process gor inte).
78	      if(n.contains(plane)){ n=n.parentElement; continue; }
79	      const cs=getComputedStyle(n); const m=/rgba?\(([^)]+)\)/.exec(cs.backgroundColor||'');
80	      if(m){ const p=m[1].split(',').map(parseFloat);
81	        if(p.length<4 || p[3]>=0.98){
82	          const r=n.getBoundingClientRect();
83	          if(r.left<=rect.left+0.5 && r.right>=rect.right-0.5 && r.top<=rect.top+0.5 && r.bottom>=rect.bottom-0.5) return true;
84	        } }
85	      n=n.parentElement;
86	    }
87	    return false;
88	  }
89	  const TEXTSEL='#process-title,.process-locked,.process-step-title,.process-p,.step-band p,.step-band h3,.step-num,.ts,h1,h2,h3';
90	  const targets=[];
91	  if(out.plane.onScreen && edgeOn>0.05){
92	    targets.push(['plane', {left:Math.max(0,V.left),right:Math.min(vw,V.right),top:Math.max(0,V.top),bottom:Math.min(vh,V.bottom)}]);
93	  }
94	  for(const li of document.querySelectorAll('.seam i')){
95	    const lcs=getComputedStyle(li); const lr=li.getBoundingClientRect();
96	    if(lr.width<=0||lr.height<=0) continue;
97	    const li2=parseInset(lcs.clipPath, lr.width, lr.height)||{top:0,right:0,bottom:0,left:0};
98	    const a={left:lr.left+li2.left,right:lr.right-li2.right,top:lr.top+li2.top,bottom:lr.bottom-li2.bottom};
99	    if(a.right<=a.left||a.bottom<=a.top) continue;
100	    if(a.bottom<0||a.top>vh||a.right<0||a.left>vw) continue;
101	    targets.push(['seam:'+(li.className||'')+'/'+(li.dataset.l||''), a]);
102	  }
103	  if(targets.length){
104	    for(const el of document.querySelectorAll(TEXTSEL)){
105	      const cs=getComputedStyle(el);
106	      if(parseFloat(cs.opacity)<0.05 || cs.visibility==='hidden' || cs.display==='none') continue;
107	      if(!(el.textContent||'').trim()) continue;
108	      let r=el.getBoundingClientRect();
109	      if(r.width<=0||r.height<=0) continue;
110	      // krymp mot forfaders clip-path (samma monster som r12:s sweep)
111	      let n=el, d=0;
112	      while(n && n.nodeType===1 && d<8){
113	        d++;
114	        const nr=n.getBoundingClientRect(); const ni=parseInset(getComputedStyle(n).clipPath, nr.width, nr.height);
115	        if(ni){ r={left:Math.max(r.left,nr.left+ni.left), right:Math.min(r.right,nr.right-ni.right),
116	                   top:Math.max(r.top,nr.top+ni.top), bottom:Math.min(r.bottom,nr.bottom-ni.bottom)}; }
117	        n=n.parentElement;
118	      }
119	      if(r.right<=r.left||r.bottom<=r.top) continue;
120	      if(r.bottom<=0||r.top>=vh) continue;
121	      for(const [nm,t] of targets){
122	        const ov={left:Math.max(r.left,t.left), right:Math.min(r.right,t.right),
123	                  top:Math.max(r.top,t.top), bottom:Math.min(r.bottom,t.bottom)};
124	        if(ov.right-ov.left<=1 || ov.bottom-ov.top<=1) continue;
125	        if(ancestorOpaqueCover(el, ov)) continue;
126	        out.hits.push({src:nm, tag:el.tagName, cls:(el.className||'').toString().slice(0,40),
127	                       txt:(el.textContent||'').trim().slice(0,30),
128	                       ov:[Math.round(ov.left),Math.round(ov.top),Math.round(ov.right),Math.round(ov.bottom)]});
129	      }
130	    }
131	  }
132	  return out;
133	}"""
