from playwright.sync_api import sync_playwright
import re

URL = "http://127.0.0.1:8795/tests/alunix-r8/runs/V3d/index.html"
WIDTHS = [320, 375, 390, 414, 768, 1024, 1280, 1440, 1920]

HEADING_JS = """
() => {
  const el = document.getElementById('process-title');
  const range = document.createRange();
  const walker = document.createTreeWalker(el, NodeFilter.SHOW_TEXT);
  let node; const rects = [];
  while ((node = walker.nextNode())) {
    for (let i = 0; i < node.length; i++) {
      const ch = node.textContent[i];
      if (/\\s/.test(ch)) continue;
      range.setStart(node, i); range.setEnd(node, i + 1);
      const r = range.getBoundingClientRect();
      if (r.width > 0) rects.push({ ch, top: Math.round(r.top) });
    }
  }
  const lines = [];
  for (const r of rects) {
    let line = lines.find(l => Math.abs(l.top - r.top) < 5);
    if (!line) { line = { top: r.top, chars: [] }; lines.push(line); }
    line.chars.push(r.ch);
  }
  return lines.map(l => l.chars.join(''));
}
"""

with sync_playwright() as p:
    b = p.chromium.launch(ignore_default_args=["--hide-scrollbars"])
    hscroll_bad = []
    for w in WIDTHS:
        pg = b.new_page(viewport={"width": w, "height": 900})
        pg.goto(URL)
        pg.wait_for_timeout(400)
        r = pg.evaluate("document.documentElement.scrollWidth - document.documentElement.clientWidth")
        if r > 1:
            hscroll_bad.append((w, r))
        if w in (390, 1440, 1920):
            lines = pg.evaluate(HEADING_JS)
            print(w, "heading lines:", lines)
        pg.close()
    print("hscroll bad:", hscroll_bad)

    # locked copy + em-dash check (full page text content)
    pg = b.new_page(viewport={"width": 1440, "height": 900})
    pg.goto(URL)
    pg.wait_for_timeout(400)
    body_text = pg.evaluate("document.body.innerText")
    em_dashes = body_text.count("—")
    print("em-dash count:", em_dashes)
    pg.close()
    b.close()

